function renderTemplate(tpl, vars) {
  return tpl.replace(
    /\{\{\s*([a-zA-Z_][a-zA-Z0-9_]*)\s*\}\}/g,
    (_match, key) => {
      if (!(key in vars)) {
        throw new Error(`renderTemplate: missing variable "${key}"`);
      }
      const v5 = vars[key];
      return typeof v5 === "string" ? v5 : JSON.stringify(v5);
    }
  );
}

