// src/stages/_shared/check-review-skip.ts
function parseIssueNumberFromBody(body) {
  if (!body) return null;
  const m2 = body.match(/Shopfloor-Issue:\s*#(\d+)/);
  return m2 ? Number(m2[1]) : null;
}
async function checkReviewSkip(adapter, prNumber) {
  const pr = await adapter.getPr(prNumber);
  if (pr.state === "closed") return { skip: true, reason: "pr_closed" };
  if (pr.draft) return { skip: true, reason: "pr_draft" };
  if (pr.labels.some((l4) => l4.name === "shopfloor:wip")) {
    return { skip: true, reason: "pr_wip_label" };
  }
  if (pr.labels.some((l4) => l4.name === "shopfloor:skip-review")) {
    return { skip: true, reason: "skip_review_label_pr" };
  }
  const originIssueNumber = parseIssueNumberFromBody(pr.body ?? null);
  if (originIssueNumber !== null) {
    const issue = await adapter.getIssue(originIssueNumber);
    if (issue.state === "closed")
      return { skip: true, reason: "origin_issue_closed" };
    if (issue.labels.some((l4) => l4.name === "shopfloor:skip-review")) {
      return { skip: true, reason: "skip_review_label_issue" };
    }
  }
  const files = await adapter.listChangedFiles(prNumber);
  if (files.length === 0) return { skip: true, reason: "no_changed_files" };
  if (files.every((f7) => f7.startsWith("docs/shopfloor/"))) {
    return { skip: true, reason: "only_shopfloor_docs" };
  }
  const reviews = await adapter.getPrReviewsAtSha(prNumber, pr.head.sha);
  const hasShopfloorReview = reviews.some(
    (r2) => r2.body.startsWith("<!-- shopfloor-review -->")
  );
  if (hasShopfloorReview)
    return { skip: true, reason: "already_reviewed_at_sha" };
  return { skip: false };
}

// src/stages/implement/apply.ts
var ITERATION_LINE = /Shopfloor-Review-Iteration:\s*(\d+)/;
function parseIterationFromBody(body) {
  if (!body) return 0;
  const m2 = body.match(ITERATION_LINE);
  if (!m2 || !m2[1]) return 0;
  return Number(m2[1]);
}
function buildImplPrBody(agentBody, issueNumber, reviewIteration) {
  return `${agentBody.trimEnd()}

---
Shopfloor-Issue: #${issueNumber}
Shopfloor-Stage: implement
Shopfloor-Review-Iteration: ${reviewIteration}
`;
}
async function applyImplement(ctx, args) {
  if (!ctx.issue) throw new Error("applyImplement requires ctx.issue");
  const { decision, progressCommentId, branchName, baseBranch } = args;
  const issueNumber = ctx.issue.number;
  if (!ctx.issue.labels.includes(LABELS.implementing)) {
    throw new Error(
      `applyImplement: refusing to finalize implement for issue #${issueNumber}: shopfloor:implementing marker is not present.`
    );
  }
  const opened = await ctx.github.openStagePr({
    base: baseBranch,
    head: branchName,
    title: decision.pr_title,
    body: decision.pr_body,
    stage: "implement",
    issueNumber,
    draft: true,
    preserveBodyIfExists: true
  });
  const existingPr = await ctx.github.getPr(opened.number);
  const reviewIteration = parseIterationFromBody(existingPr.body);
  const bodyWithFooter = buildImplPrBody(
    decision.pr_body,
    issueNumber,
    reviewIteration
  );
  await ctx.github.updatePr(opened.number, {
    title: decision.pr_title,
    body: bodyWithFooter
  });
  const finalBody = renderFinalProgress(decision);
  await finalizeProgressComment(
    ctx.github,
    progressCommentId,
    "success",
    finalBody
  );
  await ctx.github.markPullRequestReadyForReview(opened.number);
  const hasReviewApp = ctx.reviewGithub !== null;
  const skip = hasReviewApp ? await checkReviewSkip(ctx.github, opened.number) : { skip: true, reason: "no_review_app_configured" };
  const nextLabel = skip.skip ? LABELS.implInReview : LABELS.needsReview;
  await ctx.github.addLabel(issueNumber, nextLabel);
  await ctx.github.removeLabel(issueNumber, LABELS.needsImpl);
  await ctx.github.removeLabel(issueNumber, LABELS.implementing);
  await ctx.github.removeLabel(issueNumber, LABELS.reviewRequestedChanges);
  if (nextLabel === LABELS.needsReview) {
    await ctx.github.removeLabel(issueNumber, LABELS.reviewApproved);
  }
  ctx.audit({ type: "pr_opened", stage: "implement", prNumber: opened.number });
  ctx.audit({
    type: "label_applied",
    issueNumber,
    add: [nextLabel],
    remove: [
      LABELS.needsImpl,
      LABELS.implementing,
      LABELS.reviewRequestedChanges,
      ...nextLabel === LABELS.needsReview ? [LABELS.reviewApproved] : []
    ]
  });
  ctx.audit({
    type: "stage_decided",
    stage: "implement",
    decision,
    tokensUsed: 0,
    costUsd: 0
  });
  return {
    prNumber: opened.number,
    url: opened.url,
    nextLabel,
    ...skip.reason ? { skipReason: skip.reason } : {}
  };
}
function renderFinalProgress(d7) {
  const lines = [
    d7.summary_for_issue_comment,
    "",
    "### Files changed",
    ...d7.changed_files.map((f7) => `- \`${f7}\``)
  ];
  return lines.join("\n");
}

